import React from "react";
import { AbsoluteFill, Easing, Img, OffthreadVideo, Sequence, interpolate, staticFile, useCurrentFrame } from "remotion";
import {
  CREAM, GOLD, GOLD_SOLID, INK, INOUT, IcoInsta, IcoPin, Glint, Lines, Medal, NIGHT, PAPER, Photo, ROSE, ROSE_SOFT,
  SANS, SERIF, SHADOW, SHADOW_D, cl, gold, k, lin, pop,
} from "./Trancas";

// LETÍCIA TRANCISTA · roteiro 3, "qual seria a sua?". Motion vertical de 26,8 s sobre a voz do ElevenLabs (Roberta, 25,31 s,
// entra em 0,15 s). Pedido: um roteiro diferente dos dois primeiros, com César de Souza e região. Formato de escolha:
// espelho do studio com os looks trocando, "Essa? Essa? Ou essa?" com três fotos numeradas, o antes e depois, o mapa de César de Souza e uma conversa desenhada.
// Mesma identidade (creme, café, dourado, medalhão do logo). Texto sobre vídeo cheio vai embaixo, grande e com sombra
// (retorno no roteiro 2). Trocas leves: fusão com desfoque e linha dourada fina.
// Tempos = tempo da palavra na voz (transcrição em (arquivo do cliente)).

export const LE_FPS = 30;
const LEAD = 0.15;
export const LE_FRAMES = Math.round(26.8 * LE_FPS);
const fr = (s: number) => Math.max(0, Math.round((s + LEAD) * LE_FPS));

// trocas de cena (tempo da voz)
const T2 = 4.62, T3 = 8.05, T4 = 12.15, T5 = 14.75, T6 = 18.25, T7 = 22.75;

const Clip: React.FC<{ a: number; b: number; clip: number; zoom: [number, number]; t: number }> = ({ a, b, clip, zoom, t }) => (
  <Sequence from={fr(a)} durationInFrames={Math.max(1, fr(b) - fr(a))} layout="none">
    <AbsoluteFill style={{ background: NIGHT, overflow: "hidden" }}>
      <OffthreadVideo muted src={staticFile("leticia/antes-depois.mp4")} trimBefore={Math.round(clip * LE_FPS)} style={{ width: "100%", height: "100%", objectFit: "cover", transform: `scale(${interpolate(t, [a, b], zoom, { ...cl, easing: Easing.inOut(Easing.sin) }).toFixed(4)})`, transformOrigin: "50% 40%" }} />
    </AbsoluteFill>
  </Sequence>
);
const BottomShade: React.FC<{ h?: number }> = ({ h = 1000 }) => (
  <div style={{ position: "absolute", left: 0, right: 0, bottom: 0, height: h, background: "linear-gradient(0deg, rgba(42,22,13,0.92) 0%, rgba(42,22,13,0.72) 50%, rgba(42,22,13,0) 100%)" }} />
);

// ───────── cena 1 · gancho: o espelho do studio desenhado, com os looks trocando dentro (diferente do vídeo 2, que abre
// com o vídeo cheio); texto grande embaixo, no creme ─────────
const LOOKS: [number, number, string][] = [
  [1, -0.15, "50% 28%"], [6, 0.5, "50% 38%"], [2, 0.95, "50% 42%"], [4, 1.4, "50% 36%"], [3, 1.82, "40% 40%"], [1, 2.22, "50% 30%"], [6, 2.6, "50% 40%"], [2, 2.98, "50% 45%"],
];
const QUAL = 3.68;
const MX = 200, MY = 150, MW = 680, MH = 1080;
const Gancho: React.FC<{ t: number }> = ({ t }) => {
  const inn = pop(t, -0.15, 0.6);
  const q = pop(t, QUAL, 0.5);
  const blank = k(t, QUAL - 0.1, 0.3);
  return (
    <AbsoluteFill style={{ background: CREAM }}>
      {/* espelho com moldura dourada e luzes laterais, como os do studio */}
      <div style={{ position: "absolute", left: MX, top: MY, width: MW, height: MH, opacity: Math.min(1, inn * 2), transform: `translateY(${((1 - inn) * 260).toFixed(1)}px) rotate(${((1 - inn) * -7 + Math.sin(t * 1.4) * 0.7).toFixed(2)}deg) scale(${((0.7 + 0.3 * inn) * (1 + 0.04 * lin(t, 0.4, T2))).toFixed(4)})`, transformOrigin: "50% 60%" }}>
        {[0, 1].map((side) => [...Array(6)].map((_, j) => {
          const on = 0.55 + 0.45 * Math.max(0, Math.sin(t * 7 - j * 0.9 - side * 0.5));
          return <div key={`${side}-${j}`} style={{ position: "absolute", left: side ? MW + 18 : -46, top: 400 + j * 120, width: 28, height: 28, borderRadius: 14, background: "#FFF3D2", boxShadow: `0 0 ${(14 + 16 * on).toFixed(0)}px rgba(241,213,140,${(0.5 + 0.4 * on).toFixed(2)})`, opacity: k(t, 0.1 + j * 0.05, 0.3) }} />;
        }))}
        <div style={{ position: "absolute", inset: 0, borderRadius: `${MW / 2}px ${MW / 2}px 44px 44px`, backgroundImage: GOLD, boxShadow: SHADOW_D, padding: 16, boxSizing: "border-box" }}>
          <div style={{ position: "relative", width: "100%", height: "100%", borderRadius: `${MW / 2 - 16}px ${MW / 2 - 16}px 30px 30px`, overflow: "hidden", background: PAPER }}>
            {LOOKS.map(([n, at, pos], i) => {
              const next = LOOKS[i + 1]?.[1] ?? QUAL;
              if (t < at || t > next + 0.3) return null;
              const w = k(t, at, 0.24);
              return (
                <div key={i} style={{ position: "absolute", inset: 0, clipPath: `inset(0 0 ${((1 - w) * 100).toFixed(2)}% 0)` }}>
                  <Img src={staticFile(`leticia/foto-${n}.jpg`)} style={{ width: "100%", height: "100%", objectFit: "cover", objectPosition: pos, transform: `scale(${(1.12 - 0.08 * lin(t, at, next + 0.3)).toFixed(4)})` }} />
                </div>
              );
            })}
            {/* na pergunta, o espelho limpa e fica a interrogação */}
            <div style={{ position: "absolute", inset: 0, background: CREAM, opacity: blank }} />
            {t >= QUAL - 0.1 ? (
              <div style={{ position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "center" }}>
                <div style={{ fontFamily: SERIF, fontWeight: 700, fontStyle: "italic", fontSize: 560, lineHeight: 1, padding: "0 30px 40px", ...gold(), opacity: Math.min(1, q * 2), transform: `scale(${(0.3 + 0.7 * q).toFixed(3)}) rotate(${((1 - q) * -30 + Math.sin((t - QUAL) * 3) * 4).toFixed(1)}deg)` }}>?</div>
              </div>
            ) : null}
            {/* reflexo passando no vidro */}
            <Glint t={t} a={0.2} d={1.0} w={MW} />
          </div>
        </div>
      </div>
      {t < 1.85 ? <Lines t={t} top={1380} size={120} out={1.62} items={[["Se você pudesse", 0.11], ["sair hoje", 0.91]]} /> : null}
      {t >= 1.6 && t < 3.85 ? <Lines t={t} top={1380} size={120} out={3.6} items={[["com uma", 1.67], ["trança nova…", 2.06, true]]} /> : null}
      {t >= 3.6 ? (
        <div style={{ position: "absolute", left: 0, right: 0, top: 1430, display: "flex", justifyContent: "center" }}>
          <div style={{ fontFamily: SERIF, fontWeight: 700, fontStyle: "italic", fontSize: 170, lineHeight: 1.15, padding: "0 20px 18px", ...gold(), opacity: Math.min(1, q * 2), transform: `scale(${(0.5 + 0.5 * q).toFixed(3)})` }}>qual seria?</div>
        </div>
      ) : null}
    </AbsoluteFill>
  );
};

// ───────── cena 2 · essa? essa? ou essa? três fotos numeradas ─────────
const PICKS: [number, number, string, number][] = [[5, 4.9, "50% 38%", 1], [7, 6.06, "50% 30%", -1], [8, 7.11, "50% 28%", 1]];
const Escolha: React.FC<{ t: number }> = ({ t }) => (
  <AbsoluteFill style={{ background: CREAM }}>
    {PICKS.map(([, at], i) => {
      const next = PICKS[i + 1]?.[1];
      const txt = i === 2 ? "Ou essa?" : "Essa?";
      return t >= at - 0.05 && (next === undefined || t < next + 0.2) ? (
        <div key={i} style={{ position: "absolute", left: 0, right: 0, top: 190, display: "flex", justifyContent: "center" }}>
          <div style={{ fontFamily: SERIF, fontWeight: 700, fontStyle: "italic", fontSize: 140, lineHeight: 1.12, padding: "0 16px 12px", ...gold(), opacity: Math.min(1, k(t, at, 0.3) * 1.6) * (next === undefined ? 1 : 1 - lin(t, next - 0.12, next + 0.05)), filter: `blur(${((1 - k(t, at, 0.3)) * 16).toFixed(1)}px)` }}>{txt}</div>
        </div>
      ) : null;
    })}
    {PICKS.map(([n, at, pos, dir], i) => {
      if (t < at - 0.25) return null;
      const next = PICKS[i + 1]?.[1] ?? 99;
      const e = pop(t, at - 0.2, 0.45);
      const under = k(t, next - 0.2, 0.4);
      const badge = pop(t, at, 0.4);
      return (
        <div key={n} style={{ position: "absolute", left: 120, top: 470, zIndex: i, opacity: 1 - under * 0.55, transform: `translateX(${((1 - e) * 1100 * dir).toFixed(1)}px) rotate(${((1 - e) * 12 * dir + (i - 1) * 2 * e).toFixed(2)}deg) scale(${(1 - 0.08 * under).toFixed(4)})` }}>
          <Photo n={n} w={840} h={1250} pos={pos} z={1.12 - 0.1 * lin(t, at, T3 + 0.3)} />
          <div style={{ position: "absolute", right: -30, top: -40, width: 170, height: 170, borderRadius: 85, backgroundImage: GOLD, boxShadow: SHADOW_D, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: SERIF, fontWeight: 700, fontSize: 104, color: NIGHT, opacity: Math.min(1, badge * 2), transform: `scale(${badge.toFixed(3)}) rotate(${((1 - badge) * -40).toFixed(1)}deg)` }}>{i + 1}</div>
        </div>
      );
    })}
  </AbsoluteFill>
);

// ───────── cena 3 · do jeitinho que você sonhou: antes virando depois ─────────
const CLIP0 = 5.7;                                              // tempo da voz em que o arquivo está em 0 s (fusão 4,7 s → voz 10,4 s)
const Sonhou: React.FC<{ t: number }> = ({ t }) => (
  <AbsoluteFill>
    <Clip t={t} a={T3 - 0.3} b={T4 + 0.4} clip={T3 - 0.3 - CLIP0} zoom={[1.0, 1.12]} />
    <BottomShade h={950} />
    {t < 10.45 ? <Lines t={t} top={1360} size={136} color={CREAM} shadow out={10.2} items={[["Seja qual for,", 8.25], ["a Letícia faz", 9.41, true]]} /> : null}
    {t >= 10.2 ? <Lines t={t} top={1360} size={122} color={CREAM} shadow items={[["do jeitinho", 10.43], ["que você sonhou", 11.13, true]]} /> : null}
  </AbsoluteFill>
);

// ───────── cena 4 · a marca ─────────
const Marca: React.FC<{ t: number }> = ({ t }) => (
  <AbsoluteFill style={{ background: CREAM }}>
    <div style={{ position: "absolute", left: 540 - 400, top: 330, transform: `translateY(${(Math.sin((t - T4) * 1.3) * 12).toFixed(1)}px) rotate(${(Math.sin((t - T4) * 0.9) * 1.6).toFixed(2)}deg) scale(${(1 + 0.08 * lin(t, T4, T5 + 0.3)).toFixed(4)})` }}>
      <Medal t={t} a={T4 + 0.02} d={800} shine={12.9} />
    </div>
    <Lines t={t} top={1280} size={92} items={[["Especialista em", 12.62], ["tranças afro", 13.74, true]]} />
  </AbsoluteFill>
);

// ───────── cena 5 · onde: César de Souza, Mogi das Cruzes e região ─────────
const STREETS: [number, number, number, number, number][] = [
  [-100, 560, 1180, 800, 34], [-100, 1220, 1180, 1020, 26], [-100, 1560, 1180, 1700, 22], [250, 380, 380, 1920, 30], [780, 380, 650, 1920, 24], [60, 380, 1020, 1920, 14],
];
const Onde: React.FC<{ t: number }> = ({ t }) => {
  const PX = 540, PY = 1080;
  const drop = interpolate(t, [15.0, 15.4], [0, 1], { ...cl, easing: Easing.bezier(0.5, 0, 0.75, 0) });
  const land = t > 15.4 ? Math.sin(Math.min(1, (t - 15.4) / 0.45) * Math.PI) * (1 - Math.min(1, (t - 15.4) / 0.45)) : 0;
  const chip = pop(t, 15.45, 0.45);
  const area = interpolate(t, [16.41, 17.4], [0, 1], { ...cl, easing: INOUT });
  return (
    <AbsoluteFill style={{ background: CREAM }}>
      <div style={{ position: "absolute", inset: 0, transform: `scale(${(1.3 - 0.26 * interpolate(t, [T5, 18.4], [0, 1], { ...cl, easing: INOUT })).toFixed(4)}) rotate(${(-6 + 6 * interpolate(t, [T5, 18.4], [0, 1], { ...cl, easing: INOUT }) + Math.sin(t * 0.8) * 1.2).toFixed(2)}deg)`, transformOrigin: `${PX}px ${PY}px` }}>
        <svg width={1080} height={1920} style={{ position: "absolute", left: 0, top: 0 }}>
          {[[90, 640, 140, 140], [430, 600, 300, 160], [820, 560, 220, 200], [60, 900, 170, 260], [430, 870, 200, 120], [830, 860, 200, 120], [120, 1300, 120, 200], [430, 1290, 160, 180], [820, 1200, 220, 260], [200, 1680, 260, 200], [700, 1720, 300, 180]].map(([x, y, w, h], i) => (
            <rect key={i} x={x} y={y} width={w} height={h} rx={26} fill={i % 3 === 0 ? ROSE_SOFT : "#F1E7D8"} opacity={k(t, T5 - 0.2 + i * 0.04, 0.5)} />
          ))}
          {STREETS.map(([x1, y1, x2, y2, w], i) => {
            const p = k(t, T5 - 0.15 + i * 0.06, 0.7);
            return <line key={i} x1={x1} y1={y1} x2={x1 + (x2 - x1) * p} y2={y1 + (y2 - y1) * p} stroke={PAPER} strokeWidth={w} strokeLinecap="round" />;
          })}
          {/* a região: círculo que se abre em volta do alfinete */}
          <circle cx={PX} cy={PY - 60} r={60 + 380 * area} fill="rgba(214,170,80,0.10)" stroke={GOLD_SOLID} strokeWidth={5} strokeDasharray="18 14" opacity={area > 0 ? 1 : 0} transform={`rotate(${((t - 16.4) * 12).toFixed(1)} ${PX} ${PY - 60})`} />
        </svg>
        <div style={{ position: "absolute", left: PX - 80, top: PY - 190 - (1 - drop) * 900, width: 160, height: 190, opacity: t > 14.95 ? 1 : 0, transform: `scale(${(1 + 0.12 * land).toFixed(3)}, ${(1 - 0.15 * land).toFixed(3)})`, transformOrigin: "50% 100%", filter: "drop-shadow(0 18px 24px rgba(58,32,20,0.3))" }}>
          <svg width={160} height={190} viewBox="0 0 24 28.5">
            <defs><linearGradient id="lePin" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#F1D58C" /><stop offset="0.6" stopColor="#C8953C" /><stop offset="1" stopColor="#8E5E1C" /></linearGradient></defs>
            <path d="M12 0.5a10.5 10.5 0 0 0-10.5 10.5c0 7.8 10.5 17.5 10.5 17.5s10.5-9.7 10.5-17.5A10.5 10.5 0 0 0 12 0.5z" fill="url(#lePin)" />
            <circle cx={12} cy={11} r={4.2} fill={CREAM} />
          </svg>
        </div>
        <div style={{ position: "absolute", left: 0, right: 0, top: PY + 40, display: "flex", justifyContent: "center", opacity: Math.min(1, chip * 2), transform: `translateY(${((1 - chip) * 40).toFixed(1)}px) scale(${(0.6 + 0.4 * chip).toFixed(3)})` }}>
          <div style={{ padding: "22px 48px", borderRadius: 999, background: INK, boxShadow: SHADOW_D, fontFamily: SANS, fontWeight: 700, fontSize: 56, color: CREAM, whiteSpace: "nowrap" }}>César de Souza</div>
        </div>
      </div>
      <Lines t={t} top={190} size={104} items={[["Mogi das Cruzes", 16.41], ["e região", 17.49, true]]} />
    </AbsoluteFill>
  );
};

// ───────── cena 6 · ainda não sabe qual escolher? a conversa ─────────
const Bubble: React.FC<{ t: number; at: number; mine?: boolean; children: React.ReactNode; top: number }> = ({ t, at, mine, children, top }) => {
  const e = pop(t, at, 0.45);
  return (
    <div style={{ position: "absolute", top, left: mine ? undefined : 120, right: mine ? 120 : undefined, maxWidth: 760, opacity: Math.min(1, e * 2), transform: `translateY(${((1 - e) * 60 + Math.sin(t * 1.7 + top) * 5).toFixed(1)}px) scale(${(0.7 + 0.3 * e).toFixed(3)})`, transformOrigin: mine ? "100% 100%" : "0% 100%" }}>
      <div style={{ padding: "30px 40px", borderRadius: 48, [mine ? "borderBottomRightRadius" : "borderBottomLeftRadius"]: 12, background: mine ? ROSE_SOFT : INK, color: mine ? INK : CREAM, boxShadow: SHADOW, fontFamily: SANS, fontWeight: 600, fontSize: 52, lineHeight: 1.25 }}>{children}</div>
    </div>
  );
};
const Duvida: React.FC<{ t: number }> = ({ t }) => {
  const typing = t > 20.45 && t < 21.4;
  return (
    <AbsoluteFill style={{ background: CREAM }}>
      <Lines t={t} top={180} size={104} items={[["Ainda não sabe", 18.55], ["qual escolher?", 19.35, true]]} />
      <AbsoluteFill style={{ transform: `scale(${(0.96 + 0.08 * lin(t, T6, T7 + 0.3)).toFixed(4)}) translateY(${(Math.sin((t - T6) * 1.4) * 14 - 30 * lin(t, T6, T7)).toFixed(1)}px) rotate(${(Math.sin((t - T6) * 1.1) * 1.2).toFixed(2)}deg)`, transformOrigin: "540px 1100px" }}>
      {/* as três opções, pequenas, como fotos enviadas */}
      <div style={{ position: "absolute", right: 120, top: 600, display: "flex", gap: 20 }}>
        {([[5, 18.6, "50% 38%"], [7, 18.78, "50% 30%"], [8, 18.96, "50% 28%"]] as const).map(([n, at, pos], i) => {
          const e = pop(t, at, 0.4);
          return (
            <div key={n} style={{ opacity: Math.min(1, e * 2), transform: `translateY(${((1 - e) * 80 + Math.sin(t * 2 + i * 2) * 12).toFixed(1)}px) rotate(${((i - 1) * 4 * e + Math.sin(t * 1.6 + i) * 2).toFixed(1)}deg) scale(${(0.6 + 0.4 * e).toFixed(3)})` }}>
              <Photo n={n} w={240} h={320} pos={pos} z={1.05} r={26} border={false} />
            </div>
          );
        })}
      </div>
      <Bubble t={t} at={19.35} mine top={1010}>Qual combina comigo?</Bubble>
      {/* digitando… e a resposta */}
      {typing ? (
        <div style={{ position: "absolute", left: 120, top: 1300, padding: "30px 40px", borderRadius: 48, borderBottomLeftRadius: 12, background: INK, display: "flex", gap: 14, opacity: k(t, 20.45, 0.25) }}>
          {[0, 1, 2].map((d) => <div key={d} style={{ width: 20, height: 20, borderRadius: 10, background: "#F1D58C", transform: `translateY(${(-10 * Math.max(0, Math.sin((t - 20.45) * 14 - d * 0.9))).toFixed(1)}px)` }} />)}
        </div>
      ) : null}
      <Bubble t={t} at={21.45} top={1300}>Te ajudo a decidir! ✨</Bubble>
      {/* avatar do studio junto da resposta */}
      <div style={{ position: "absolute", left: 120, top: 1480, display: "flex", alignItems: "center", gap: 16, opacity: k(t, 21.6, 0.4) }}>
        <div style={{ width: 76, height: 76, borderRadius: 38, overflow: "hidden", border: `3px solid ${GOLD_SOLID}`, background: PAPER }}>
          <Img src={staticFile("leticia/logo.png")} style={{ width: 84, height: 84, margin: -4 }} />
        </div>
        <span style={{ fontFamily: SANS, fontWeight: 600, fontSize: 38, color: INK }}>Letícia Trancista</span>
      </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// ───────── cena 7 · fecho ─────────
const Fecho: React.FC<{ t: number }> = ({ t }) => {
  const btn = pop(t, 22.96, 0.5);
  const press = interpolate(t, [23.95, 24.05, 24.27], [0, 1, 0], cl);
  const rip = lin(t, 24.0, 24.65);
  const chip = k(t, 24.45, 0.45);
  const handle = k(t, 24.75, 0.45);
  return (
    <AbsoluteFill style={{ background: CREAM }}>
      <div style={{ position: "absolute", left: 540 - 320, top: 260, transform: `scale(${(1 + 0.05 * lin(t, T7, 26.7)).toFixed(4)}) translateY(${(Math.sin((t - T7) * 1.2) * 10).toFixed(1)}px)` }}>
        <Medal t={t} a={T7 + 0.02} d={640} shine={25.0} />
      </div>
      <div style={{ position: "absolute", left: 0, right: 0, top: 1070, display: "flex", justifyContent: "center" }}>
        <div style={{ position: "relative", opacity: Math.min(1, btn * 2), transform: `scale(${((0.5 + 0.5 * btn) * (1 - 0.06 * press)).toFixed(4)})` }}>
          {rip > 0 && rip < 1 ? <div style={{ position: "absolute", inset: 0, borderRadius: 999, border: `4px solid ${GOLD_SOLID}`, transform: `scale(${(1 + 0.25 * rip).toFixed(3)}, ${(1 + 0.7 * rip).toFixed(3)})`, opacity: 1 - rip }} /> : null}
          <div style={{ position: "relative", overflow: "hidden", padding: "36px 74px", borderRadius: 999, backgroundImage: GOLD, boxShadow: SHADOW_D, fontFamily: SANS, fontWeight: 700, fontSize: 58, color: NIGHT, whiteSpace: "nowrap" }}>
            Agende a sua trança
            <Glint t={t} a={24.3} d={0.8} w={760} />
          </div>
        </div>
      </div>
      <div style={{ position: "absolute", left: 0, right: 0, top: 1330, display: "flex", justifyContent: "center", opacity: chip, transform: `translateY(${((1 - chip) * 40).toFixed(1)}px)` }}>
        <div style={{ display: "flex", alignItems: "center", gap: 12, padding: "18px 36px 18px 28px", borderRadius: 999, background: INK, boxShadow: SHADOW }}>
          <IcoPin s={42} c={ROSE} />
          <span style={{ fontFamily: SANS, fontWeight: 600, fontSize: 40, color: CREAM, whiteSpace: "nowrap" }}>César de Souza · Mogi das Cruzes</span>
        </div>
      </div>
      <div style={{ position: "absolute", left: 0, right: 0, top: 1520, display: "flex", justifyContent: "center", alignItems: "center", gap: 16, opacity: handle, transform: `translateY(${((1 - handle) * 40).toFixed(1)}px)` }}>
        <IcoInsta s={50} c={INK} />
        <span style={{ fontFamily: SANS, fontWeight: 600, fontSize: 44, color: INK }}>@suamarca</span>
      </div>
    </AbsoluteFill>
  );
};

const Soft: React.FC<{ t: number; at: number; d?: number; children: React.ReactNode }> = ({ t, at, d = 0.45, children }) => {
  const e = interpolate(t, [at - d / 2, at + d / 2], [0, 1], { ...cl, easing: INOUT });
  return <AbsoluteFill style={{ opacity: e, filter: e < 1 ? `blur(${((1 - e) * 22).toFixed(1)}px)` : undefined, transform: `scale(${(1.06 - 0.06 * e).toFixed(4)})` }}>{children}</AbsoluteFill>;
};
const GoldLine: React.FC<{ t: number; at: number }> = ({ t, at }) => {
  const p = lin(t, at - 0.3, at + 0.3);
  if (p <= 0 || p >= 1) return null;
  return <div style={{ position: "absolute", left: -200, right: -200, top: -100 + p * 2120, height: 6, backgroundImage: GOLD, boxShadow: "0 0 30px rgba(241,213,140,0.8)", transform: "rotate(-8deg)" }} />;
};

export const LeticiaEscolha: React.FC = () => {
  const t = useCurrentFrame() / LE_FPS - LEAD;
  const scenes: [number, number, React.FC<{ t: number }>][] = [
    [-1, T2, Gancho], [T2, T3, Escolha], [T3, T4, Sonhou], [T4, T5, Marca], [T5, T6, Onde], [T6, T7, Duvida], [T7, 99, Fecho],
  ];
  return (
    <AbsoluteFill style={{ background: CREAM }}>
      {scenes.map(([a, b, S], i) => {
        if (t < a - 0.3 || t > b + 0.3) return null;
        return i === 0 ? <AbsoluteFill key={i}><S t={t} /></AbsoluteFill> : <Soft key={i} t={t} at={a}><S t={t} /></Soft>;
      })}
      {[T2, T4, T6].map((a) => <GoldLine key={a} t={t} at={a} />)}
    </AbsoluteFill>
  );
};

import { loadFont as loadPlayfair } from "@remotion/google-fonts/PlayfairDisplay";
import { loadFont as loadMontserrat } from "@remotion/google-fonts/Montserrat";
