// LETÍCIA TRANCISTA · studio de tranças afro em Mogi das Cruzes. Motion vertical de 33,5 s sobre a voz do ElevenLabs
// (Roberta, 32,13 s, entra em 0,15 s). Identidade do logo: medalhão dourado com borda trançada, café e creme; o rosa vem
// das paredes do studio. Tom feminino, acolhedor e elegante.
// Gancho com celular desenhado e tranças genéricas (o problema); as fotos do studio estreiam em "Uma trança nova".
// Limpo: fundo liso, texto entra e fica parado; o movimento contínuo fica nas fotos, nos objetos e nas trocas.
// Tempos = tempo da palavra na voz (transcrição em (arquivo do cliente)).

export const { fontFamily: SERIF } = loadPlayfair("normal", { weights: ["600", "700"], subsets: ["latin", "latin-ext"] });
loadPlayfair("italic", { weights: ["600", "700"], subsets: ["latin", "latin-ext"] });
export const { fontFamily: SANS } = loadMontserrat("normal", { weights: ["500", "600", "700"], subsets: ["latin", "latin-ext"] });
export const { fontFamily: SCRIPT } = loadVibes("normal", { weights: ["400"], subsets: ["latin", "latin-ext"] });

export const LT_FPS = 30;
const LEAD = 0.15;
export const LT_FRAMES = Math.round(33.5 * LT_FPS);

export const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
export const OUT = Easing.bezier(0.16, 1, 0.3, 1);
export const BACK = Easing.out(Easing.back(1.5));
export const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
export const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
export const pop = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
export const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);

export const CREAM = "#FBF6EE";
export const PAPER = "#FFFFFF";
export const INK = "#3A2014";
export const MUTED = "#8A6B58";
export const LINE = "#EADFCF";
export const NIGHT = "#2A160D";
export const ROSE = "#E9A9C1";
export const ROSE_SOFT = "#F7DDE7";
export const GOLD = "linear-gradient(100deg, #8E5E1C 0%, #C8953C 28%, #F1D58C 52%, #C08A34 74%, #8E5E1C 100%)";
export const GOLD_SOLID = "#B8862F";
export const SHADOW = "0 30px 70px rgba(58,32,20,0.14), 0 4px 14px rgba(58,32,20,0.08)";
export const SHADOW_D = "0 44px 90px rgba(58,32,20,0.30), 0 8px 20px rgba(58,32,20,0.14)";

// trocas de cena (tempo da voz)
const T2 = 4.95, T3 = 7.95, T4 = 13.2, T5 = 20.1, T6 = 23.0, T7 = 26.1, T8 = 29.45;

export const blurIn = (t: number, at: number, out?: number, d = 0.45): React.CSSProperties => {
  const e = k(t, at, d);
  const o = out === undefined ? 0 : lin(t, out, out + 0.2);
  return {
    opacity: Math.min(1, e * 1.6) * (1 - o),
    filter: `blur(${((1 - e) * 18 + o * 14).toFixed(1)}px)`,
    transform: `scale(${(0.9 + 0.1 * e).toFixed(4)})`,
  };
};
export const gold = (): React.CSSProperties => ({ backgroundImage: GOLD, WebkitBackgroundClip: "text", backgroundClip: "text", color: "transparent" });

export type L = [string, number, boolean?];
export const Lines: React.FC<{ t: number; items: L[]; size: number; top: number; color?: string; out?: number; italic?: boolean; shadow?: boolean }> = ({ t, items, size, top, color = INK, out, italic, shadow }) => (
  <div style={{ position: "absolute", left: 0, right: 0, top, display: "flex", flexDirection: "column", alignItems: "center", filter: shadow ? "drop-shadow(0 6px 18px rgba(20,10,5,0.75))" : undefined }}>
    {items.map(([w, at, hl], i) => (
      <div key={i} style={{ fontFamily: SERIF, fontWeight: 700, fontStyle: hl || italic ? "italic" : "normal", fontSize: size, lineHeight: 1.12, letterSpacing: "-0.02em", whiteSpace: "nowrap", color, padding: `0 ${size * 0.08}px ${size * 0.1}px`, ...(hl ? gold() : {}), ...blurIn(t, at, out) }}>
        {w}
      </div>
    ))}
  </div>
);

// foto do studio num cartão: recorte por objectPosition, zoom lento a partir do ponto de interesse
export const Photo: React.FC<{ n: number; w: number; h: number; pos: string; z: number; r?: number; border?: boolean }> = ({ n, w, h, pos, z, r = 44, border = true }) => (
  <div style={{ position: "relative", width: w, height: h, borderRadius: r, overflow: "hidden", background: LINE, boxShadow: SHADOW_D }}>
    <Img src={staticFile(`leticia/foto-${n}.jpg`)} style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover", objectPosition: pos, transform: `scale(${z.toFixed(4)})`, transformOrigin: pos }} />
    {border ? <div style={{ position: "absolute", inset: 0, borderRadius: r, border: "3px solid rgba(241,213,140,0.85)", boxSizing: "border-box" }} /> : null}
  </div>
);

// brilho que atravessa um cartão
export const Glint: React.FC<{ t: number; a: number; d?: number; w?: number }> = ({ t, a, d = 0.9, w = 1200 }) => {
  const p = lin(t, a, a + d);
  if (p <= 0 || p >= 1) return null;
  return <div style={{ position: "absolute", top: -400, bottom: -400, width: 260, left: -500 + p * (w + 900), transform: "rotate(18deg)", background: "linear-gradient(90deg, rgba(255,246,220,0) 0%, rgba(255,246,220,0.55) 50%, rgba(255,246,220,0) 100%)", pointerEvents: "none" }} />;
};

