// ───────── cena 1 · gancho (o problema): a trança fica salva no celular ─────────
const TILE_BG = [ROSE_SOFT, "#EFDFCB", "#F4E9D8", "#EBCFDA", "#E6D5C1", "#F9E6EC"];
const Hook: React.FC<{ t: number }> = ({ t }) => {
  const SAVE = 1.77, SAD = 3.1;
  const inn = pop(t, -0.15, 0.55);
  const scroll = 980 * interpolate(t, [-0.05, 1.65], [0, 1], { ...cl, easing: Easing.bezier(0.3, 0, 0.2, 1) }) + Math.max(0, t - 1.65) * 22;
  const heart = pop(t, SAVE, 0.4);
  const heartOut = lin(t, SAVE + 0.9, SAVE + 1.2);
  const ring = lin(t, SAVE, SAVE + 0.45);
  const toast = k(t, SAVE + 0.1, 0.35);
  const sad = k(t, SAD, 0.9);
  const count = Math.round(127 + 6 * lin(t, SAD + 0.1, 4.6));
  const PH = { x: 270, y: 640, w: 540, h: 1100 };
  return (
    <AbsoluteFill style={{ background: CREAM }}>
      {t < SAD + 0.2 ? <Lines t={t} top={200} size={104} out={SAD - 0.15} items={[["Aquela trança", 0.8], ["que você salva", 1.5]]} /> : null}
      {t >= SAD - 0.05 ? <Lines t={t} top={200} size={104} items={[["e fica só", SAD], ["na vontade?", 4.09, true]]} /> : null}
      <div style={{ position: "absolute", left: PH.x, top: PH.y, width: PH.w, height: PH.h, opacity: Math.min(1, inn * 2), transform: `translateY(${((1 - inn) * 260 + sad * 34).toFixed(1)}px) rotate(${((1 - inn) * -9 + sad * 4 + Math.sin(t * 1.6) * 0.8).toFixed(2)}deg) scale(${(0.7 + 0.3 * inn - 0.04 * sad).toFixed(4)})` }}>
        <div style={{ position: "absolute", inset: 0, borderRadius: 78, background: INK, boxShadow: SHADOW_D }} />
        <div style={{ position: "absolute", left: 16, top: 16, right: 16, bottom: 16, borderRadius: 64, background: CREAM, overflow: "hidden", filter: `grayscale(${(sad * 0.75).toFixed(2)})` }}>
          {/* miniaturas rolando */}
          <div style={{ position: "absolute", left: 22, top: 150 - scroll, display: "flex", flexWrap: "wrap", gap: 12, width: 464 }}>
            {[...Array(33)].map((_, i) => <BraidThumb key={i} w={146} h={194} bg={TILE_BG[(i * 5) % TILE_BG.length]} v={i} />)}
          </div>
          {/* barra de cima: pasta de salvos */}
          <div style={{ position: "absolute", left: 0, right: 0, top: 0, height: 132, background: CREAM, display: "flex", alignItems: "flex-end", justifyContent: "center", paddingBottom: 22, boxSizing: "border-box", gap: 12, borderBottom: `2px solid ${LINE}` }}>
            <IcoBookmark s={34} c={INK} />
            <span style={{ fontFamily: SANS, fontWeight: 700, fontSize: 34, color: INK }}>Salvos</span>
            <span style={{ fontFamily: SANS, fontWeight: 600, fontSize: 30, color: MUTED, fontVariantNumeric: "tabular-nums" }}>· {count}</span>
          </div>
          {/* toque duplo: coração */}
          {t >= SAVE && heartOut < 1 ? (
            <div style={{ position: "absolute", left: 254 - 150, top: 534 - 150, width: 300, height: 300, display: "flex", alignItems: "center", justifyContent: "center", opacity: 1 - heartOut }}>
              <div style={{ position: "absolute", width: 300, height: 300, borderRadius: 150, border: `${(10 * (1 - ring)).toFixed(1)}px solid ${ROSE}`, transform: `scale(${(0.3 + 0.9 * ring).toFixed(3)})`, opacity: 1 - ring }} />
              <div style={{ transform: `scale(${(0.2 + 0.8 * heart).toFixed(3)})`, filter: "drop-shadow(0 16px 30px rgba(58,32,20,0.25))" }}><IcoHeart s={200} c={ROSE} /></div>
            </div>
          ) : null}
          {/* aviso de salvo */}
          <div style={{ position: "absolute", left: 0, right: 0, bottom: 46, display: "flex", justifyContent: "center", opacity: toast, transform: `translateY(${((1 - toast) * 60).toFixed(1)}px)` }}>
            <div style={{ display: "flex", alignItems: "center", gap: 12, padding: "16px 30px", borderRadius: 999, background: INK, boxShadow: SHADOW }}>
              <IcoBookmark s={30} c={ROSE} />
              <span style={{ fontFamily: SANS, fontWeight: 600, fontSize: 30, color: CREAM }}>Salvo para depois</span>
            </div>
          </div>
        </div>
      </div>
      {/* salvando de novo e de novo: marcadores voando para a pasta */}
      {[3.3, 3.62, 3.94, 4.26].map((a, i) => {
        const u = lin(t, a, a + 0.5);
        if (u <= 0 || u >= 1) return null;
        const sx = [180, 900, 150, 930][i], sy = [1500, 1420, 1100, 1250][i];
        const e = Easing.inOut(Easing.cubic)(u);
        return (
          <div key={i} style={{ position: "absolute", left: sx + (540 - sx) * e - 30, top: sy + (PH.y + 100 - sy) * e - 30 - Math.sin(Math.PI * u) * 120, opacity: Math.sin(Math.PI * u) * 1.4, transform: `rotate(${((1 - u) * (i % 2 ? 30 : -30)).toFixed(1)}deg) scale(${(1.2 - 0.6 * u).toFixed(2)})` }}>
            <IcoBookmark s={60} c={GOLD_SOLID} />
          </div>
        );
      })}
    </AbsoluteFill>
  );
};

