// ───────── medalhão do logo: círculo recortado do arquivo, anel dourado que se desenha ─────────
export const Medal: React.FC<{ t: number; a: number; d: number; shine?: number }> = ({ t, a, d, shine }) => {
  const drawn = interpolate(t, [a - 0.05, a + 0.6], [0, 1], { ...cl, easing: INOUT });
  const inn = pop(t, a + 0.12, 0.6);
  const img = d / 0.904;                     // o anel do arquivo ocupa 89% da largura; recorte em 45,2% do raio
  const R = d / 2 + 14, C = 2 * Math.PI * R;
  return (
    <div style={{ position: "relative", width: d, height: d }}>
      <svg width={d + 60} height={d + 60} style={{ position: "absolute", left: -30, top: -30, transform: `rotate(${(-90 + (t - a) * 6).toFixed(2)}deg)` }}>
        <circle cx={d / 2 + 30} cy={d / 2 + 30} r={R} fill="none" stroke={GOLD_SOLID} strokeWidth={4} strokeLinecap="round" strokeDasharray={`${(C * drawn).toFixed(1)} ${C}`} />
      </svg>
      <div style={{ position: "absolute", inset: 0, borderRadius: "50%", overflow: "hidden", boxShadow: SHADOW, background: PAPER, opacity: Math.min(1, inn * 2), transform: `scale(${(0.72 + 0.28 * inn).toFixed(4)})`, filter: `blur(${((1 - k(t, a + 0.12, 0.5)) * 14).toFixed(1)}px)` }}>
        <Img src={staticFile("leticia/logo.png")} style={{ position: "absolute", width: img, height: img, left: (d - img) / 2, top: (d - img) / 2, transform: `scale(${(1 + 0.03 * interpolate(t, [a, a + 5], [0, 1], { ...cl, easing: Easing.inOut(Easing.sin) })).toFixed(4)}) rotate(${(Math.sin((t - a) * 0.9) * 2).toFixed(2)}deg)` }} />
        {shine !== undefined ? <Glint t={t} a={shine} d={1.0} w={d} /> : null}
      </div>
    </div>
  );
};

