// ───────── cena 4 · os estilos, uma foto por batida, e para quem ─────────
type Cut = { n: number; a: number; pos: string; dir: number };
const CUTS: Cut[] = [
  { n: 5, a: T4 - 0.1, pos: "50% 38%", dir: 1 },
  { n: 6, a: 13.95, pos: "50% 38%", dir: -1 },
  { n: 2, a: 14.46, pos: "50% 45%", dir: 1 },
  { n: 7, a: 15.3, pos: "50% 30%", dir: -1 },
  { n: 4, a: 16.22, pos: "50% 38%", dir: 1 },
];
const FAN_AT = 17.2;
const Estilos: React.FC<{ t: number }> = ({ t }) => {
  const label = (txt: string, at: number, out: number) => (t >= at - 0.05 && t < out + 0.25 ? (
    <div style={{ position: "absolute", left: 0, right: 0, top: 200, display: "flex", justifyContent: "center" }}>
      <div style={{ fontFamily: SERIF, fontWeight: 700, fontStyle: "italic", fontSize: 132, lineHeight: 1.12, letterSpacing: "-0.02em", padding: "0 14px 12px", ...gold(), ...blurIn(t, at, out, 0.35) }}>{txt}</div>
    </div>
  ) : null);
  const fanOut = lin(t, FAN_AT - 0.15, FAN_AT + 0.15);
  return (
    <AbsoluteFill style={{ background: CREAM }}>
      {label("Box braids", 13.39, 14.28)}
      {label("Boho", 14.46, 15.95)}
      {t >= 15.4 && t < 16.2 ? <Lines t={t} top={370} size={60} color={MUTED} out={15.95} items={[["cheia de cachos", 15.44]]} italic /> : null}
      {label("Nagô", 16.22, FAN_AT - 0.2)}
      {/* baralho de fotos: cada uma entra de um lado, com impulso */}
      {t < FAN_AT + 0.2 ? CUTS.map((c, i) => {
        const next = CUTS[i + 1]?.a ?? FAN_AT;
        if (t < c.a - 0.02 || t > next + 0.5) return null;
        const e = pop(t, c.a, 0.42);
        const under = next < FAN_AT ? k(t, next, 0.4) : 0;
        const z = 1.12 - 0.1 * lin(t, c.a, next + 0.4);
        return (
          <div key={c.n} style={{ position: "absolute", left: 120, top: 520, zIndex: i, opacity: (1 - fanOut) * (1 - under * 0.6), transform: `translateX(${((1 - e) * 1100 * c.dir).toFixed(1)}px) rotate(${((1 - e) * 14 * c.dir + (i % 2 ? -1.2 : 1.2) * e).toFixed(2)}deg) scale(${(1 - 0.08 * under - 0.1 * fanOut).toFixed(4)})` }}>
            <Photo n={c.n} w={840} h={1220} pos={c.pos} z={z} />
          </div>
        );
      }) : null}
      {/* pra ela, pra ele e pras pequenas */}
      {t >= FAN_AT - 0.05 ? (
        <>
          <Lines t={t} top={180} size={92} items={[["Pra ela,", FAN_AT], ["pra ele", 17.98], ["e pras pequenas", 18.74, true]]} />
          {([[7, FAN_AT, 70, 790, -8, 430, 600, "50% 30%"], [3, 17.98, 580, 790, 8, 430, 600, "35% 30%"], [8, 18.74, 290, 900, 0, 500, 760, "50% 28%"]] as const).map(([n, at, x, y, r, w, h, pos], i) => {
            const e = pop(t, at, 0.5);
            const grow = i === 2 ? k(t, 19.3, 0.8) : 0;
            return (
              <div key={n} style={{ position: "absolute", left: x, top: y, zIndex: 10 + i, opacity: Math.min(1, e * 2), transform: `translateY(${((1 - e) * 500 + Math.sin(t * 1.8 + i * 2) * 8).toFixed(1)}px) rotate(${(r * e + (1 - e) * (i - 1) * 20).toFixed(2)}deg) scale(${(0.7 + 0.3 * e + 0.06 * grow).toFixed(4)})` }}>
                <Photo n={n} w={w} h={h} pos={pos} z={1.1 - 0.08 * lin(t, at, T5)} r={36} />
              </div>
            );
          })}
        </>
      ) : null}
    </AbsoluteFill>
  );
};

// ───────── cena 5a · o tempo é parte do cuidado: a trança dourada sendo feita ─────────
const Cuidado: React.FC<{ t: number }> = ({ t }) => {
  const N = 15, STEP = 64, TOP = 700;
  return (
    <AbsoluteFill style={{ background: NIGHT }}>
      <Lines t={t} top={220} size={90} color={CREAM} items={[["Aqui, o tempo", 20.38], ["é parte do cuidado.", 21.66, true]]} />
      <svg width={1080} height={1920} style={{ position: "absolute", left: 0, top: 0, transform: `rotate(${(Math.sin(t * 1.1) * 2.2).toFixed(2)}deg) translateY(${(Math.sin(t * 0.9) * 10).toFixed(1)}px)`, transformOrigin: "540px 700px" }}>
        <defs>
          <linearGradient id="ltGold" x1="0" y1="0" x2="1" y2="1">
            <stop offset="0" stopColor="#8E5E1C" /><stop offset="0.45" stopColor="#F1D58C" /><stop offset="1" stopColor="#B07A2A" />
          </linearGradient>
        </defs>
        {[...Array(N)].map((_, j) => {
          const at = 20.45 + j * 0.15;
          const e = pop(t, at, 0.4);
          if (e <= 0) return null;
          const y = TOP + j * STEP, side = j % 2 ? 1 : -1;
          return (
            <g key={j} opacity={Math.min(1, e * 2)} transform={`translate(${540 + side * 30} ${y}) rotate(${side * -34}) scale(${(0.4 + 0.6 * e).toFixed(3)})`}>
              <ellipse cx={0} cy={0} rx={44} ry={84} fill="url(#ltGold)" />
              <ellipse cx={-8} cy={-14} rx={14} ry={46} fill="rgba(255,248,225,0.35)" />
            </g>
          );
        })}
        {/* ponta da trança com conta dourada */}
        {(() => {
          const e = pop(t, 20.45 + N * 0.15, 0.5);
          const y = TOP + N * STEP + 20;
          return e > 0 ? (
            <g opacity={e} transform={`translate(540 ${y}) scale(${e.toFixed(3)})`}>
              <rect x={-36} y={-30} width={72} height={60} rx={16} fill="url(#ltGold)" />
              <path d="M-14 30 L0 110 L14 30 Z" fill="url(#ltGold)" opacity={0.85} />
            </g>
          ) : null;
        })()}
      </svg>
    </AbsoluteFill>
  );
};

// ───────── cena 5b · cada trança, a sua beleza ─────────
const TILES: [number, number, number, number, string][] = [
  [1, 23.3, 120, 640, "50% 28%"], [6, 23.62, 560, 640, "50% 40%"], [3, 24.12, 120, 1200, "40% 40%"], [7, 24.64, 560, 1200, "50% 30%"],
];
const Beleza: React.FC<{ t: number }> = ({ t }) => {
  const star = pop(t, 25.46, 0.45);
  return (
    <AbsoluteFill style={{ background: CREAM }}>
      <Lines t={t} top={180} size={92} items={[["Cada trança feita", 23.22], ["pra realçar", 24.46], ["a sua beleza", 25.32, true]]} />
      {TILES.map(([n, at, x, y, pos], i) => {
        const e = pop(t, at, 0.45);
        return (
          <div key={n} style={{ position: "absolute", left: x, top: y + Math.sin(t * 1.7 + i * 1.6) * 7, opacity: Math.min(1, e * 2), transform: `translate(${((1 - e) * (i % 2 ? 260 : -260)).toFixed(1)}px, ${((1 - e) * 120).toFixed(1)}px) rotate(${((1 - e) * (i % 2 ? 10 : -10)).toFixed(2)}deg) scale(${(0.8 + 0.2 * e).toFixed(4)})` }}>
            <Photo n={n} w={400} h={520} pos={pos} z={1.14 - 0.1 * lin(t, at, T7 + 0.3)} r={34} />
          </div>
        );
      })}
      {star > 0 ? (
        <div style={{ position: "absolute", left: 540 - 60, top: 1160 - 60, width: 120, height: 120, borderRadius: 60, background: INK, display: "flex", alignItems: "center", justifyContent: "center", boxShadow: SHADOW_D, opacity: Math.min(1, star * 2), transform: `scale(${star.toFixed(3)}) rotate(${((t - 25.46) * 60).toFixed(1)}deg)` }}>
          <IcoSpark s={70} c="#F1D58C" />
        </div>
      ) : null}
    </AbsoluteFill>
  );
};

// ───────── cena 6 · agenda aberta, vagas limitadas ─────────
const FREE = [9, 17, 22, 26];                                   // as que sobram
const ORDER = [3, 14, 0, 20, 7, 25, 11, 1, 18, 5, 27, 12, 23, 8, 15, 2, 21, 6, 13, 24, 4, 19, 10, 16];
const Agenda: React.FC<{ t: number }> = ({ t }) => {
  const A = 26.34, B = 27.66, LAST = 28.58;
  const card = pop(t, T7 + 0.05, 0.55);
  const CW = 96, CH = 104, G = 16;
  return (
    <AbsoluteFill style={{ background: CREAM }}>
      {t < B + 0.25 ? <Lines t={t} top={230} size={110} out={B - 0.15} items={[["Agenda aberta", A]]} /> : null}
      {t >= B - 0.05 ? <Lines t={t} top={230} size={110} items={[["Vagas limitadas", B, true]]} /> : null}
      <div style={{ position: "absolute", left: 120, top: 620, width: 840, height: 740, borderRadius: 56, background: PAPER, border: `2px solid ${LINE}`, boxSizing: "border-box", boxShadow: SHADOW, opacity: Math.min(1, card * 2), transform: `translateY(${((1 - card) * 240 + Math.sin(t * 1.6) * 6).toFixed(1)}px) rotate(${((1 - card) * -6 + Math.sin(t * 1.2) * 0.6).toFixed(2)}deg) scale(${(0.82 + 0.18 * card).toFixed(4)})` }}>
        <div style={{ position: "absolute", left: 50, right: 50, top: 50, display: "flex", alignItems: "center", justifyContent: "space-between" }}>
          <span style={{ fontFamily: SERIF, fontWeight: 700, fontSize: 64, color: INK }}>Agenda</span>
          <div style={{ padding: "12px 28px", borderRadius: 999, background: t < LAST ? ROSE_SOFT : INK, fontFamily: SANS, fontWeight: 700, fontSize: 32, color: t < LAST ? INK : "#F1D58C", transform: `scale(${(1 + 0.12 * (t >= LAST ? 1 - k(t, LAST, 0.4) : 0)).toFixed(3)})` }}>{t < LAST ? "Aberta" : "Últimas vagas"}</div>
        </div>
        <div style={{ position: "absolute", left: 36, top: 200, width: 7 * CW + 6 * G, display: "flex", flexWrap: "wrap", gap: G }}>
          {[...Array(28)].map((_, i) => {
            const e = pop(t, A - 0.1 + ((i % 7) + Math.floor(i / 7)) * 0.05, 0.4);
            const oi = ORDER.indexOf(i);
            const takenAt = oi < 0 ? Infinity : B + oi * 0.055;
            const taken = oi < 0 ? 0 : k(t, takenAt, 0.25);
            const free = FREE.includes(i);
            const glow = free && t > LAST ? 0.5 + 0.5 * Math.sin((t - LAST) * 6 + i) : 0;
            return (
              <div key={i} style={{ width: CW, height: CH, borderRadius: 24, boxSizing: "border-box", border: `3px solid ${taken > 0.5 ? INK : GOLD_SOLID}`, background: taken > 0 ? `rgba(58,32,20,${taken.toFixed(2)})` : PAPER, display: "flex", alignItems: "center", justifyContent: "center", position: "relative", opacity: Math.min(1, e * 2), transform: `scale(${(0.5 + 0.5 * e + 0.1 * (taken > 0 && taken < 1 ? 1 - taken : 0)).toFixed(3)})`, boxShadow: glow ? `0 0 ${(18 + 18 * glow).toFixed(0)}px rgba(214,170,80,${(0.45 + 0.4 * glow).toFixed(2)})` : undefined }}>
                {taken > 0 ? <IcoCheck s={52} c={CREAM} p={taken} /> : <span style={{ fontFamily: SANS, fontWeight: 600, fontSize: 36, color: free && t > LAST ? GOLD_SOLID : INK }}>{i + 1}</span>}
              </div>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

// ───────── cena 7 · fecho: marca, horário e o Instagram ─────────
const Fecho: React.FC<{ t: number }> = ({ t }) => {
  const btn = pop(t, 29.62, 0.5);
  const press = interpolate(t, [30.3, 30.4, 30.62], [0, 1, 0], cl);
  const rip = lin(t, 30.35, 31.0);
  const handle = k(t, 31.4, 0.45);
  return (
    <AbsoluteFill style={{ background: CREAM }}>
      <div style={{ position: "absolute", left: 540 - 320, top: 250 }}>
        <Medal t={t} a={T8 + 0.02} d={640} shine={31.6} />
      </div>
      <div style={{ position: "absolute", left: 0, right: 0, top: 1040, display: "flex", justifyContent: "center" }}>
        <div style={{ position: "relative", opacity: Math.min(1, btn * 2), transform: `scale(${((0.5 + 0.5 * btn) * (1 - 0.06 * press)).toFixed(4)})` }}>
          {rip > 0 && rip < 1 ? <div style={{ position: "absolute", inset: 0, borderRadius: 999, border: `4px solid ${GOLD_SOLID}`, transform: `scale(${(1 + 0.25 * rip).toFixed(3)}, ${(1 + 0.7 * rip).toFixed(3)})`, opacity: 1 - rip }} /> : null}
          <div style={{ position: "relative", overflow: "hidden", padding: "34px 70px", borderRadius: 999, backgroundImage: GOLD, boxShadow: SHADOW_D, fontFamily: SANS, fontWeight: 700, fontSize: 54, color: NIGHT, letterSpacing: "0.005em", whiteSpace: "nowrap" }}>
            Garanta o seu horário
            <Glint t={t} a={30.5} d={0.8} w={760} />
          </div>
        </div>
      </div>
      <div style={{ position: "absolute", left: 0, right: 0, top: 1250, textAlign: "center", fontFamily: SCRIPT, fontSize: 170, lineHeight: 1.3, ...blurIn(t, 31.01, undefined, 0.5) }}>
        <span style={{ ...gold(), padding: "0 30px" }}>Vem viver essa!</span>
      </div>
      <div style={{ position: "absolute", left: 0, right: 0, top: 1610, display: "flex", justifyContent: "center", alignItems: "center", gap: 16, opacity: handle, transform: `translateY(${((1 - handle) * 40).toFixed(1)}px)` }}>
        <IcoInsta s={50} c={INK} />
        <span style={{ fontFamily: SANS, fontWeight: 600, fontSize: 44, color: INK }}>@suamarca</span>
      </div>
    </AbsoluteFill>
  );
};

export const LeticiaTrancas: React.FC = () => {
  const t = useCurrentFrame() / LT_FPS - LEAD;
  // trocas, cada uma de um jeito: mergulho na tela do celular · íris · empurrão lateral · faixa dourada inclinada ·
  // folha que sobe · recuo · duas metades
  const dive = interpolate(t, [T2 - 0.22, T2 + 0.22], [0, 1], { ...cl, easing: Easing.in(Easing.cubic) });
  const reveal = interpolate(t, [T2, T2 + 0.35], [0, 1], { ...cl, easing: OUT });
  const iris = interpolate(t, [T3 - 0.22, T3 + 0.28], [0, 1], { ...cl, easing: INOUT });
  const push = interpolate(t, [T4 - 0.26, T4 + 0.22], [0, 1], { ...cl, easing: INOUT });
  const band = interpolate(t, [T5 - 0.3, T5 + 0.3], [0, 1], { ...cl, easing: INOUT });
  const sheet = interpolate(t, [T6 - 0.28, T6 + 0.22], [0, 1], { ...cl, easing: OUT });
  const back = interpolate(t, [T7 - 0.22, T7 + 0.2], [0, 1], { ...cl, easing: INOUT });
  const split = interpolate(t, [T8 - 0.2, T8 + 0.24], [0, 1], { ...cl, easing: INOUT });
  return (
    <AbsoluteFill style={{ background: CREAM }}>
      {t < T2 + 0.25 ? (
        <AbsoluteFill style={{ transform: `scale(${(1 + 3.2 * dive).toFixed(4)})`, transformOrigin: "540px 1190px", opacity: 1 - lin(t, T2 + 0.05, T2 + 0.22) }}><Hook t={t} /></AbsoluteFill>
      ) : null}
      {t >= T2 - 0.02 && t < T3 + 0.3 ? (
        <AbsoluteFill style={{ opacity: reveal, transform: `scale(${(1.1 - 0.1 * reveal).toFixed(4)})` }}><Virada t={t} /></AbsoluteFill>
      ) : null}
      {t >= T3 - 0.24 && t < T4 + 0.25 ? (
        <AbsoluteFill style={{ clipPath: t < T3 + 0.3 ? `circle(${(iris * 2300).toFixed(0)}px at 540px 820px)` : undefined, transform: `translateX(${(-push * 1080).toFixed(1)}px)` }}><Marca t={t} /></AbsoluteFill>
      ) : null}
      {t >= T4 - 0.28 && t < T5 + 0.32 ? (
        <AbsoluteFill style={{ transform: `translateX(${((1 - push) * 1080).toFixed(1)}px)` }}><Estilos t={t} /></AbsoluteFill>
      ) : null}
      {t >= T5 - 0.02 && t < T6 + 0.25 ? <AbsoluteFill><Cuidado t={t} /></AbsoluteFill> : null}
      {t >= T5 - 0.32 && t < T5 + 0.32 ? (
        <div style={{ position: "absolute", left: 540 - 1000, top: -500, width: 2000, height: 2920, backgroundImage: GOLD, transform: `rotate(18deg) translateX(${((band - 0.5) * 2 * 2700).toFixed(1)}px)` }} />
      ) : null}
      {t >= T6 - 0.3 && t < T7 + 0.22 ? (
        <AbsoluteFill style={{ transform: `translateY(${((1 - sheet) * 1920).toFixed(1)}px) scale(${(1 - 0.1 * back).toFixed(4)})`, opacity: 1 - back, borderRadius: `${((1 - sheet) * 90).toFixed(0)}px ${((1 - sheet) * 90).toFixed(0)}px 0 0`, overflow: "hidden", boxShadow: "0 -30px 80px rgba(0,0,0,0.25)" }}><Beleza t={t} /></AbsoluteFill>
      ) : null}
      {t >= T7 - 0.22 && t < T8 + 0.26 ? (
        <AbsoluteFill style={{ opacity: t < T7 + 0.2 ? back : 1, transform: `scale(${(1.12 - 0.12 * back).toFixed(4)})` }}><Agenda t={t} /></AbsoluteFill>
      ) : null}
      {t >= T8 - 0.22 ? (
        <AbsoluteFill style={{ clipPath: `inset(${((1 - split) * 50).toFixed(2)}% 0 ${((1 - split) * 50).toFixed(2)}% 0)` }}><Fecho t={t} /></AbsoluteFill>
      ) : null}
    </AbsoluteFill>
  );
};

